Does this compile under `strict: true`?

```ts
class Dog { name = ''; }
class Cat { name = ''; }

const d: Dog = new Cat();
```

Which call is reported as an error?

```ts
interface Point { x: number; y: number }
function show(p: Point) {}

const pt = { x: 1, y: 2, z: 3 };
show(pt);                    // call 1
show({ x: 1, y: 2, z: 3 });  // call 2
```

What does TypeScript report for this code?

```ts
const a: readonly number[] = [1, 2];
a.push(3);
```

What does TypeScript report for this interface?

```ts
interface Dict {
  [key: string]: number;
  count: string;
}
```

Which line does TypeScript flag?

```ts
interface Opts { url: string }
function req(o: Opts) {}

const extra = { url: '/a', retries: 3 };
req(extra);                                // 1
req({ url: '/a', retries: 3 } as Opts);    // 2
req({ url: '/a', retries: 3 });            // 3
const copy: Opts = { ...extra };           // 4
```

Does this compile?

```ts
type Shape =
  | { kind: 'circle'; r: number }
  | { kind: 'square'; size: number };

const s: Shape = { kind: 'circle', r: 1, size: 2 };
```

What does TypeScript report?

```ts
interface Options { verbose?: boolean; color?: boolean }

const input = { verbos: true };
const o: Options = input;
```

With `strict: true` (which includes `strictFunctionTypes`), which line is an error?

```ts
type Animal = { name: string };
type Dog = Animal & { bark(): void };

interface M { handle(a: Animal): void }    // method syntax
interface P { handle: (a: Animal) => void } // property syntax

const fd = (d: Dog) => d.bark();
const m: M = { handle: fd };  // line 1
const p: P = { handle: fd };  // line 2
```

This compiles under `strict: true`. What happens when it runs?

```ts
class Animal { name = 'a'; }
class Dog extends Animal { bark() { return 'woof'; } }

const dogs: Dog[] = [new Dog()];
const animals: Animal[] = dogs;
animals.push(new Animal());
dogs[1].bark();
```

Which lines are errors?

```ts
class A { private x = 1; }
class B { private x = 1; }
class P1 { x = 1; }
class P2 { x = 1; }

const a: A = new B();      // 1
const p: P1 = new P2();    // 2
const lit: A = { x: 1 };   // 3
```

With `noUncheckedIndexedAccess: true`, what are the types of `first`, `val`, `s` and `t0`?

```ts
declare const arr: string[];
declare const dict: Record<string, number>;
declare const tup: [string, number];

const first = arr[0];
const val = dict['k'];
for (const s of arr) { /* ... */ }
const t0 = tup[0];
```

Which lines are errors?

```ts
type UserId = string & { readonly __brand: 'UserId' };
type OrderId = string & { readonly __brand: 'OrderId' };
function getUser(id: UserId) {}

const raw = 'u1';
getUser(raw);                    // 1
const uid = raw as UserId;
getUser(uid);                    // 2
const oid = 'o1' as OrderId;
getUser(oid);                    // 3
const len: number = uid.length;  // 4
```

This compiles under `strict: true`. What happens when it runs, and why did the compiler allow it?

```ts
const full = { a: 1, b: 'text' };
const narrow: { a: number } = full;
const opt: { a: number; b?: number } = narrow;
const n = opt.b?.toFixed(2);
```

Which assignment is an error?

```ts
interface IPerson { name: string }
type TPerson = { name: string };
declare const i: IPerson;
declare const t: TPerson;

const r1: Record<string, string> = t;  // 1
const r2: Record<string, string> = i;  // 2
const r3: object = i;                  // 3
```

Which two lines compile? (Choose two.)

```ts
class A { #x = 1; }
class B { #x = 1; }
class Base { protected id = 1; }
class Sub extends Base {}
class Other { protected id = 1; }
class Pub { id = 1; }

const a: A = new B();        // 1
const b1: Base = new Sub();  // 2
const b2: Base = new Other(); // 3
const b3: Base = new Pub();  // 4
class Merged {}
interface Merged { extra: number }
declare const mm: Merged;
const e: number = mm.extra;  // 5
```

Which assignment is an error under `strict: true`?

```ts
class Animal { name = 'a'; }
class Dog extends Animal { bark() {} }

interface Cmp1<T> { compare(a: T, b: T): number }    // method syntax
interface Cmp2<T> { compare: (a: T, b: T) => number } // property syntax

declare let a1: Cmp1<Animal>; declare let d1: Cmp1<Dog>;
declare let a2: Cmp2<Animal>; declare let d2: Cmp2<Dog>;

a1 = d1;                                   // 1
a2 = d2;                                   // 2
const animals: Animal[] = [new Dog()];     // 3
```
